return ['domain'=>'simple-tags','plural-forms'=>'nplurals=1; plural=0;','language'=>'id-ID','project-id-version'=>'PublishPress Taxonomies Free 3.53.0','pot-creation-date'=>'2026-09-04T13:08:23+00:00','po-revision-date'=>'2026-10-31 02:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Taxonomies Free'=>'PublishPress Taxonomies Free','https://wordpress.org/plugins/simple-tags/'=>'https://wordpress.org/plugins/simple-tags/','PublishPress Taxonomies allows you to create and manage Tags, Categories, and all your WordPress taxonomy terms.'=>'PublishPress Taxonomies memungkinkan Anda untuk membuat dan mengelola Tag, Kategori, dan semua istilah taksonomi WordPress Anda.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Here'=>'Di sini',' Select current post'=>' Pilih pos saat ini','Current Posts (PublishPress Taxonomies)'=>'Pos Saat Ini (PublishPress Taxonomies)','this page.'=>'halaman ini.','Select related post'=>'Pilih pos terkait','Related Posts (PublishPress Taxonomies)'=>'Pos Terkait (PublishPress Taxonomies)','Select Terms Display'=>'Pilih Tampilan Istilah','Terms Display (PublishPress Taxonomies)'=>'Tampilan Istilah (PublishPress Taxonomies)','Permission denied.'=>'Izin ditolak.','The batch limit must be between 1 and %d posts.'=>'Batas batch harus antara 1 dan %d pos.','The batch wait time must be between 0 and %d seconds.'=>'Waktu tunggu batch harus antara 0 dan %d detik.','Auto Term is required, kindly add an Auto Term from Auto Term menu.'=>'Auto Term diperlukan, silakan tambahkan Auto Term dari menu Auto Term.','Limit per batches is required.'=>'Batas per batch diperlukan.','Batches wait time is required.'=>'Waktu tunggu per batch diperlukan.','Auto term settings not found'=>'Pengaturan Auto Term tidak ditemukan','The selected Auto Term setting is not enabled for any post type. Please select at least one post type in the Auto Term settings.'=>'Pengaturan Auto Term yang dipilih tidak diaktifkan untuk jenis p